-- The commission letter to the agent: the invoice line reworded, and the company it is made out to.
-- Only the exact old sentence is replaced, so any other wording the office changed stays.
UPDATE "email_templates" SET "body" = replace("body", 'Please send us your invoice for it, and we will settle it and send you the receipt.', E'Please send us the invoice for it and we will proceed with the payment accordingly.\n\nPlease issue the invoice under the company name: Dex-ino'), "body_el" = replace("body_el", 'Παρακαλούμε στείλτε μας το τιμολόγιό σας, και θα την εξοφλήσουμε και θα σας στείλουμε την απόδειξη.', E'Παρακαλούμε στείλτε μας το τιμολόγιο και θα προχωρήσουμε με την πληρωμή αναλόγως.\n\nΠαρακαλούμε εκδώστε το τιμολόγιο στο όνομα της εταιρείας: Dex-ino'), "updated_at" = now() WHERE "key" = 'agent_commission';
